#!/bin/bash
# Runs Stainless on the ASN1SCC Scala code generated by scripts/regen-asn1.sh.
#
#   [MODE=safety|invertibility] scripts/verify-asn1.sh [name...]
#
# MODE=safety (default) verifies the code ASN1SCC generates without
# -stainlessInvertibility: absence of runtime errors, termination, and the
# exact encoded size and stream position of every codec. MODE=invertibility
# verifies the code generated with it, which adds decode(encode(v)) == v
# for SEQUENCE types and prefix lemmas; it is much slower.
#
# Only the generated functions (package asn1src) are verification targets;
# calls into the asn1scala runtime library are checked against the
# library's contracts. The summary of each run is written to
# asn1-formats/results/<name>.txt, the full Stainless output and JSON report
# to asn1-formats/build/<name>/.
#
#   STAINLESS        stainless launcher (default: stainless)
#   STAINLESS_CONF   stainless.conf (default: asn1-formats/stainless.conf)
#   TIMEOUT          per-VC timeout in seconds (default: 120)
#   MODE             safety (default) or invertibility
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
STAINLESS="${STAINLESS:-stainless}"
CONF="${STAINLESS_CONF:-$ROOT/asn1-formats/stainless.conf}"
MODE="${MODE:-safety}"
case "$MODE" in
  safety) sub=scala-safety ;;
  invertibility) sub=scala ;;
  *) echo "MODE must be safety or invertibility"; exit 2 ;;
esac
names=("$@")
if [ ${#names[@]} -eq 0 ]; then
  for pat in "$ROOT"/formats/*.hexpat; do names+=("$(basename "$pat" .hexpat)"); done
fi
mkdir -p "$ROOT/asn1-formats/results"
for name in "${names[@]}"; do
  build="$ROOT/asn1-formats/build/$name"
  [ -d "$build/$sub" ] || { echo "$name: not built (run scripts/regen-asn1.sh)"; continue; }
  cd "$build/$sub"
  fns=$(grep -ohE "^ *(@[a-zA-Z]+ )*def [A-Za-z0-9_]+" src/main/scala/asn1src/*.scala | grep -oE "def [A-Za-z0-9_]+" | sed 's/def //' | sort -u | paste -sd, -)
  srcs=$(ls src/main/scala/asn1scala/asn1jvm*.scala src/main/scala/asn1src/*.scala | grep -v "Codec_PER\|Codec_UPER")
  start=$(date +%s)
  "$STAINLESS" $srcs --config-file="$CONF" --timeout="${TIMEOUT:-120}" \
    --functions="$fns" --json="$build/stainless-$MODE.json" > "$build/stainless-$MODE.log" 2>&1
  status=$?
  end=$(date +%s)
  sed 's/\x1b\[[0-9;]*m//g' "$build/stainless-$MODE.log" | tr '\r' '\n' > "$build/stainless-$MODE.txt"
  {
    echo "format: $name ($MODE)"
    echo "stainless exit status: $status"
    echo "wall time: $((end - start)) s"
    grep -a -E "total: [0-9]+" "$build/stainless-$MODE.txt" | tail -1 | sed 's/^.*\(total:\)/\1/; s/ *[^0-9a-z:. ()]*$//; s/ *$//'
    echo
    echo "VCs that are not valid:"
    grep -a -E " (invalid|unknown|timeout) " "$build/stainless-$MODE.txt" | grep -a -v "total:" | sed 's/^\[[^]]*\] *[^ ]* *//; s/ *[^ ]* *$//; s/  */ /g' | head -100
  } > "$ROOT/asn1-formats/results/$name.$MODE.txt"
  head -4 "$ROOT/asn1-formats/results/$name.$MODE.txt"
done
